css:
.nps {
    background-color: var(--wby-color-surface-raised, #f7f7f9);
    background-image: url("https://g5-assets-cld-res.cloudinary.com/image/upload/x_0,y_0,h_3600,w_6000,c_crop/q_auto,f_auto,fl_lossy,g_center,h_960,w_1600/v1773910860/g5/g5-c-6ab10zxdi-mutual-housing-association-of-southwestern-connecticut-inc/g5-cl-1qv2b33m0t-mutual-housing-association-of-southwestern-connecticut-inc-bridgeport-ct/uploads/Denver_Background_Tertiary_bnx4vk.png");
    background-size: cover;
    background-position: 50% 50%;
    background-repeat: no-repeat;
    padding: 60px var(--wby-space-container-padding, 25px);
    display: flex;
    justify-content: center;
    align-items: center;
}

.nps-card {
    width: 100%;
    max-width: 1013px;
    background-color: var(--wby-color-surface-page, #ffffff);
    padding: 45px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
    text-align: center;
}

.nps-eyebrow {
    font-family: gravesend-sans, var(--wby-type-heading-5-family, Inter), sans-serif;
    font-size: var(--wby-type-heading-5-size, 18px);
    line-height: 18px;
    font-weight: 300;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--wby-color-action-secondary-background, #6c733d);
    text-align: center;
}

.nps-heading {
    font-family: nobel-condensed, Georgia, Cambria, "Times New Roman", Times, serif;
    font-size: var(--wby-type-heading-3-size, 45px);
    line-height: 45px;
    font-weight: 400;
    text-transform: uppercase;
    color: var(--wby-color-action-secondary-background, #6c733d);
    text-align: center;
    max-width: 923px;
    margin: 0 auto;
}

.nps-heading :global(a) {
    color: inherit;
    text-decoration: none;
}

.nps-body {
    font-family: stevie-sans, proxima-nova, "Helvetica Neue", Helvetica, Roboto, Arial, sans-serif;
    font-size: var(--wby-type-body-size, 16px);
    line-height: var(--wby-type-body-line-height, 22px);
    font-weight: 400;
    color: var(--wby-color-text-primary, #444444);
    text-align: center;
    max-width: 923px;
    margin: 0 auto;
}

.nps-body a {
    font-weight: 700;
    color: var(--wby-color-action-primary-background, #a65f46);
    text-decoration: none;
}

.nps-body a:hover {
    text-decoration: underline;
}

@media (max-width: 768px) {
    .nps-card {
        padding: 32px 24px;
    }
    .nps-heading {
        font-size: 2rem;
        line-height: 1.2;
    }
    .nps-body {
        font-size: 15px;
    }
}

source:
export default function NeighborhoodPerksSection({ inputs: { eyebrow, heading, body } }) {
    return (
        <section className="nps">
            <div className="nps-card">
                {eyebrow ? <div className="nps-eyebrow">{eyebrow}</div> : null}
                {heading ? (
                    <div className="nps-heading" dangerouslySetInnerHTML={{ __html: heading }} />
                ) : null}
                {body ? (
                    <div className="nps-body" dangerouslySetInnerHTML={{ __html: body }} />
                ) : null}
            </div>
        </section>
    );
}

export const manifest = {
    name: "Custom/NeighborhoodPerksSection",
    label: "Neighborhood Perks Section",
    applyDefaultStyles: false,
    aiContext: "A neighborhood highlights section with an eyebrow label, large heading, and descriptive body text inside a white card over a textured background. Use to describe local area perks or community amenities.",
    inputs: [
        { name: "heading", factory: "createLexicalInput", params: { label: "Heading", defaultValue: "in Bridgeport" } },
        { name: "eyebrow", factory: "createTextInput", params: { label: "Eyebrow", defaultValue: "Perks of Living" } },
        { name: "body", factory: "createLexicalInput", params: { label: "Body", defaultValue: "Experience <a href=\"https://www.parkcityplace.org/apartments/ct/bridgeport/neighborhood\">ultimate neighborhood</a> convenience when you choose to live at Park City Place in a coveted neighborhood of Bridgeport. Located just around the corner from major roadways and highway access points, you\u2019ll live just moments from the best destinations in the city. With access to daily conveniences and endless opportunities for play, this neighborhood is where you want to be." } }
    ]
};
